function() {
  var cUserId = {{[VAR] Cookie - userID}};
  var dtUserId = {{[VAR] DataLayer - userID}};
  var invalidValuesRegex = /^(|unidentified|undefined|null|not set|no id|guest)$/i;

  function isValidUserId(value) {
    return !(value === null || 
             value === undefined || 
             String(value).trim() === '' || 
             invalidValuesRegex.test(String(value).trim()));
  }

  if (isValidUserId(cUserId)) {
    return cUserId;
  } 
  else if (isValidUserId(dtUserId)) {
    return dtUserId;
  } 
  else {
    return undefined;
  }
}

