function() {
  // Captura a URL de destino do clique
  var urlDestino = {{Click URL}} || "";

  // Mapeamento de termos contidos na URL para a taxonomia correspondente
  var dicionarioBotoes = {

    // BV
    'parceiroComercial/484634': 'emprestimo - simule agora - bv',

    // OLX / Pagamentos
    'message=parceledoiscartoes': 'pagamento - compre agora - olx',
    'message=pixcomdesconto': 'pagamento - compre agora - olx',
    'message=nupay24x': 'pagamento - compre agora - nupay',
    'message=botaoeasycredito': 'emprestimo - compre agora - easycredito',

    // Klubi /
    'consorcio/pesado': 'consorcio - simular pesado - klubi',
    'imovel/selecao-credito': 'consorcio - simular imovel - klubi',
    'consorcio/celular': 'consorcio - simular celular - klubi',
    'klubi.com.br/auto': 'consorcio - simular carro - klubi',
    'olx/moto': 'consorcio - simular moto - klubi',

    // OLX / Financiamentos
    'message=financiamentosimularcarro': 'financiamento - simular carro - olx',
    'message=financiamentosimularmoto': 'financiamento - simular moto - olx'
  };

  // Avalia se a URL do clique contém alguma das chaves mapeadas
  for (var termoChave in dicionarioBotoes) {
    if (urlDestino.indexOf(termoChave) !== -1) {
      return dicionarioBotoes[termoChave];
    }
  }

  // Caso a URL não esteja mapeada, avalia se o elemento possui texto visível
  var textoNativo = {{Click Text}};
  if (textoNativo && textoNativo.trim() !== "") {
    return textoNativo.trim().toLowerCase(); 
  }

  // Retorna undefined se o elemento não possuir texto e a URL não estiver mapeada
  return undefined;
}

